var t=`0205-croquetas-de-jamon`;var n=`world-0205`;var a=`ES`;var o=`southern-europe`;var l=4;var r=184;var s={en:`Croquetas de Jamón`,ua:`Крокети з хамоном`};var u={en:`A traditional Spain dish made with all-purpose flour, whole cow milk, serrano ham, chicken egg. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: пшеничне борошно універсальне, цільне коров'яче молоко, хамон серрано, куряче яйце. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Make a very thick béchamel by cooking butter and flour briefly and whisking in milk little by little. Continue stirring until it releases cleanly from the pan.`,ua:`Приготуйте дуже густий бешамель: прогрійте масло з борошном і поступово введіть молоко, постійно збиваючи. Доведіть до маси, що відстає від стінок сотейника.`,t:[`roux-making`],m:9,i:[[`unsalted-butter`,70,`g`],[`all-purpose-flour`,85,`g`],[`whole-cow-milk`,550,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`serrano-ham`,180,`g`],[`ground-nutmeg`,2,`g`],[`table-salt`,null,`to_taste`]]},{en:`Spread the ham béchamel in a shallow dish, cover its surface and chill thoroughly until firm enough to shape into croquettes.`,ua:`Розподіліть бешамель із хамоном у пласкій формі, накрийте поверхню та добре охолодіть до щільності, придатної для формування крокетів.`,t:[`rapid-chilling`],m:150,i:[]},{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:8,i:[[`chicken-egg`,2,`pcs`],[`breadcrumbs`,150,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 12 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 12 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:12,i:[[`sunflower-oil`,500,`ml`]]}];var d={slug:t,id:n,country:`ES`,region:o,servings:4,minutes:184,title:s,text:u,steps:h};export{a as country,d as default,n as id,r as minutes,o as region,l as servings,t as slug,h as steps,u as text,s as title};